{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw, ImageOps
im = Image.open('radiograph.jpg').convert('L')
def grid_zoom(name, box, scale=2.5, cutoff=0.5):
    c = im.crop(box)
    c = ImageOps.autocontrast(c, cutoff=cutoff)
    c = c.convert('RGB').resize((int((box[2]-box[0])*scale), int((box[3]-box[1])*scale)), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for gx in range(0, box[2]-box[0]+1, 25):
        d.line([(gx*scale,0),(gx*scale,c.height)], fill=(255,60,60), width=1)
        if gx % 50 == 0: d.text((gx*scale+2, 2), str(box[0]+gx), fill=(255,220,0))
    for gy in range(0, box[3]-box[1]+1, 25):
        d.line([(0,gy*scale),(c.width,gy*scale)], fill=(255,60,60), width=1)
        if gy % 50 == 0: d.text((2, gy*scale+2), str(box[1]+gy), fill=(255,220,0))
    c.save(f'H_{name}.png')
    print(name, c.size)

grid_zoom('UR1', (380, 350, 780, 720))    # upper right molars + below
grid_zoom('LR2', (560, 500, 1060, 880))   # lower right premolar-molar
EOF", "description": "High-mag zooms of upper-right and lower-right teeth"}

